import math

def stable_small_root(b, c):
    return 2 * c / (b + math.sqrt(b * b - 4 * c))

def welford_var(xs):
    mean, m2, n = 0.0, 0.0, 0
    for x in xs:
        n += 1
        d = x - mean
        mean += d / n
        m2 += d * (x - mean)
    return m2 / (n - 1)

def best_bump(f, x):
    h = 2.220446049250313e-16 ** (1 / 3) * max(1.0, abs(x))
    return (f(x + h) - f(x - h)) / (2 * h)
